function pathStroke(color,width,offset=0){
  ctx.beginPath();ctx.moveTo(-100,810+offset);ctx.bezierCurveTo(450,755+offset,550,810+offset,900,860+offset);ctx.bezierCurveTo(1260,920+offset,1390,780+offset,1710,815+offset);ctx.bezierCurveTo(1900,835+offset,1960,780+offset,2250,800+offset);ctx.strokeStyle=color;ctx.lineWidth=width;ctx.lineCap='round';ctx.stroke();
}
function drawGround(){
  ctx.fillStyle='#bd8954';ctx.fillRect(0,0,W,H);
  // Broad, sun-baked bands of soil
  for(let i=0;i<34;i++){
    const x=rand(i+411)*W,y=rand(i+812)*H,r=110+rand(i+52)*230;
    ctx.fillStyle=i%2?'rgba(224,175,111,.085)':'rgba(111,68,39,.055)';ctx.beginPath();ctx.ellipse(x,y,r,r*(.28+rand(i+13)*.32),rand(i)*3,0,Math.PI*2);ctx.fill();
  }
  // A winding wagon track, plus its wheel ruts
  pathStroke('rgba(128,78,43,.27)',82);pathStroke('rgba(224,174,111,.35)',63);
  pathStroke('rgba(116,73,43,.22)',2,-13);pathStroke('rgba(116,73,43,.22)',2,13);
  // Distant eroded ridges and dry riverbeds
  ctx.fillStyle='#9f704d';ctx.beginPath();ctx.moveTo(0,70);ctx.lineTo(170,145);ctx.lineTo(375,80);ctx.lineTo(590,173);ctx.lineTo(790,93);ctx.lineTo(1010,164);ctx.lineTo(1230,76);ctx.lineTo(1450,153);ctx.lineTo(1690,83);ctx.lineTo(1880,153);ctx.lineTo(2130,79);ctx.lineTo(2400,130);ctx.lineTo(2400,0);ctx.lineTo(0,0);ctx.closePath();ctx.fill();
  ctx.fillStyle='#a97950';ctx.beginPath();ctx.moveTo(0,1470);ctx.lineTo(240,1360);ctx.lineTo(455,1478);ctx.lineTo(710,1375);ctx.lineTo(960,1490);ctx.lineTo(1170,1370);ctx.lineTo(1430,1490);ctx.lineTo(1710,1360);ctx.lineTo(1960,1475);ctx.lineTo(2180,1380);ctx.lineTo(2400,1460);ctx.lineTo(2400,1600);ctx.lineTo(0,1600);ctx.closePath();ctx.fill();
  ctx.strokeStyle='rgba(236,187,124,.24)';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(80,1450);ctx.quadraticCurveTo(240,1375,390,1458);ctx.moveTo(850,1460);ctx.quadraticCurveTo(1000,1390,1140,1450);ctx.stroke();
  for(const r of rocks){
    ctx.save();ctx.translate(r.x,r.y);ctx.rotate(r.rot);
    ctx.fillStyle='rgba(86,55,36,.12)';ctx.beginPath();ctx.ellipse(4,5,r.r*1.35,r.r*.75,0,0,Math.PI*2);ctx.fill();
    ctx.fillStyle=r.shade>.5?'#9a704e':'#a97b53';ctx.beginPath();ctx.moveTo(-r.r,-r.r*.25);ctx.lineTo(-r.r*.35,-r.r*.78);ctx.lineTo(r.r*.64,-r.r*.61);ctx.lineTo(r.r,r.r*.05);ctx.lineTo(r.r*.35,r.r*.65);ctx.lineTo(-r.r*.75,r.r*.52);ctx.closePath();ctx.fill();
    ctx.strokeStyle='rgba(232,185,129,.35)';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(-r.r*.35,-r.r*.55);ctx.lineTo(r.r*.52,-r.r*.38);ctx.stroke();ctx.restore();
  }
  for(const p of plants){drawPlant(p.x,p.y,p.s,p.rot);}
  // Dry branches and scattered pebbles
  for(let i=0;i<110;i++){const x=rand(i+1811)*W,y=rand(i+1921)*H;if(y>720&&y<900&&x<2100)continue;ctx.strokeStyle='rgba(93,61,38,.44)';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+7+rand(i+88)*13,y-4-rand(i+41)*8);ctx.lineTo(x+17+rand(i+202)*11,y+2);ctx.stroke();}
}
function drawPlant(x,y,s,rot){
  ctx.save();ctx.translate(x,y);ctx.rotate(rot);ctx.scale(s,s);
  ctx.fillStyle='rgba(68,59,34,.18)';ctx.beginPath();ctx.ellipse(3,5,12,6,0,0,Math.PI*2);ctx.fill();
  ctx.strokeStyle='#65703e';ctx.lineWidth=3;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(0,5);ctx.lineTo(0,-13);ctx.moveTo(0,-4);ctx.lineTo(-7,-8);ctx.lineTo(-7,-13);ctx.moveTo(0,0);ctx.lineTo(7,-4);ctx.lineTo(7,-10);ctx.stroke();
  ctx.fillStyle='#d5a25e';ctx.beginPath();ctx.arc(-.5,-15,2.2,0,Math.PI*2);ctx.fill();ctx.restore();
}
function drawBuilding(b){
  ctx.save();ctx.translate(b.x,b.y);const {w,h,type}=b;
  ctx.fillStyle='rgba(56,35,23,.3)';ctx.fillRect(-w/2+8,-h/2+13,w,h);
  if(type==='rock'){
    ctx.fillStyle='#806445';ctx.beginPath();ctx.moveTo(-w/2,-h*.15);ctx.lineTo(-w*.26,-h/2);ctx.lineTo(w*.18,-h*.44);ctx.lineTo(w/2,-h*.1);ctx.lineTo(w*.36,h/2);ctx.lineTo(-w*.34,h*.42);ctx.closePath();ctx.fill();ctx.strokeStyle='#c19b6d';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-w*.25,-h*.34);ctx.lineTo(w*.12,-h*.3);ctx.stroke();
  }else if(type==='well'){
    ctx.fillStyle='#75604b';ctx.fillRect(-w/2,-h/2,w,h);ctx.fillStyle='#b5956c';ctx.fillRect(-w/2+6,-h/2+6,w-12,h-12);ctx.fillStyle='#322d27';ctx.beginPath();ctx.ellipse(0,0,23,17,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#dfbb87';ctx.lineWidth=4;ctx.beginPath();ctx.ellipse(0,0,25,19,0,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#5e503f';ctx.fillRect(30,-h/2+5,4,24);ctx.fillRect(47,-h/2+5,4,24);ctx.strokeStyle='#4b3b2b';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(27,-h/2+4);ctx.lineTo(54,-h/2+4);ctx.stroke();
  }else if(type==='tent'){
    ctx.fillStyle='#74533b';ctx.beginPath();ctx.moveTo(-w/2,-h/2+8);ctx.lineTo(w*.05,-h/2-9);ctx.lineTo(w/2,h/2-8);ctx.lineTo(-w/2,h/2);ctx.closePath();ctx.fill();ctx.fillStyle='#a6784d';ctx.beginPath();ctx.moveTo(-w/2,-h/2+8);ctx.lineTo(w*.05,-h/2-9);ctx.lineTo(4,h/2-1);ctx.closePath();ctx.fill();ctx.strokeStyle='#d0a774';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(4,h/2-2);ctx.lineTo(4,3);ctx.stroke();
  }else{
    const station=type==='station';ctx.fillStyle=station?'#8f5739':'#805640';ctx.fillRect(-w/2,-h/2,w,h);
    ctx.fillStyle=station?'#b6784b':'#9e6d49';ctx.beginPath();ctx.moveTo(-w/2-8,-h/2+5);ctx.lineTo(-w/2+14,-h/2-13);ctx.lineTo(w/2-10,-h/2-13);ctx.lineTo(w/2+8,-h/2+5);ctx.lineTo(w/2,h/2);ctx.lineTo(-w/2,h/2);ctx.closePath();ctx.fill();
    ctx.strokeStyle='#d6ab76';ctx.lineWidth=3;ctx.strokeRect(-w/2+9,-h/2+12,w-18,h-23);
    ctx.fillStyle='#46362b';ctx.fillRect(-10,h/2-26,20,26);
    ctx.fillStyle='#e7c491';ctx.font='bold 11px Oswald';ctx.textAlign='center';ctx.fillText(station?'SANTA LUZIA':'BAR DO SOL',0,-h/2+9);
    if(station){ctx.fillStyle='#6b5140';ctx.fillRect(-w/2-35,h/2+17,w+70,5);ctx.fillRect(-w/2-35,h/2+27,w+70,5);for(let i=0;i<8;i++){ctx.fillRect(-w/2-30+i*27,h/2+13,4,20);}}
  }
  ctx.restore();
}
function drawClue(s,i){
  if(state.clues[i])return;
  const pulse=.5+Math.sin(state.time*3+i)*.5;
  ctx.save();ctx.translate(s.x,s.y);ctx.fillStyle=`rgba(255,215,146,${.12+pulse*.12})`;ctx.beginPath();ctx.arc(0,0,22+pulse*5,0,Math.PI*2);ctx.fill();
  ctx.strokeStyle='#f0c47e';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(0,-9);ctx.lineTo(8,0);ctx.lineTo(0,9);ctx.lineTo(-8,0);ctx.closePath();ctx.stroke();
  ctx.fillStyle='#ffdfaa';ctx.beginPath();ctx.arc(0,0,3,0,Math.PI*2);ctx.fill();
  ctx.font='9px DM Mono';ctx.textAlign='center';ctx.fillStyle='rgba(255,232,193,.8)';ctx.fillText('CLUE',0,-27-pulse*2);ctx.restore();
}
function drawEnemy(e){
  if(e.hp<=0)return;ctx.save();ctx.translate(e.x,e.y);ctx.rotate(e.angle);
  ctx.fillStyle='rgba(50,31,24,.25)';ctx.beginPath();ctx.ellipse(1,8,14,9,0,0,Math.PI*2);ctx.fill();
  ctx.fillStyle='#44362d';ctx.beginPath();ctx.ellipse(0,1,8,12,0,0,Math.PI*2);ctx.fill();
  ctx.fillStyle='#a34f36';ctx.fillRect(-8,-3,16,5);
  ctx.fillStyle='#ce9b68';ctx.beginPath();ctx.arc(0,-8,6,0,Math.PI*2);ctx.fill();
  ctx.fillStyle='#30251d';ctx.beginPath();ctx.ellipse(0,-11,11,4,0,0,Math.PI*2);ctx.fill();ctx.fillRect(-5,-16,10,5);
  ctx.strokeStyle='#352920';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(6,-1);ctx.lineTo(17,-4);ctx.stroke();
  ctx.restore();
}
function drawPlayer(){
  const p=state.player;if(p.invuln>0&&Math.floor(state.time*18)%2===0)return;
  ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.angle);
  ctx.fillStyle='rgba(47,30,20,.32)';ctx.beginPath();ctx.ellipse(1,8,17,11,0,0,Math.PI*2);ctx.fill();
  const bob=Math.sin(p.stride)*1.5;
  ctx.fillStyle='#263c36';ctx.beginPath();ctx.ellipse(0,bob,9,13,0,0,Math.PI*2);ctx.fill();
  ctx.fillStyle='#d4a675';ctx.beginPath();ctx.arc(0,-9+bob,6.5,0,Math.PI*2);ctx.fill();
  ctx.fillStyle='#34251b';ctx.beginPath();ctx.ellipse(0,-13+bob,13,5,0,0,Math.PI*2);ctx.fill();ctx.fillRect(-6,-19+bob,12,5);
  ctx.fillStyle='#b54731';ctx.fillRect(-8,-2+bob,16,4);
  ctx.strokeStyle='#29221b';ctx.lineWidth=3.5;ctx.beginPath();ctx.moveTo(5,-2+bob);ctx.lineTo(19,-4+bob);ctx.stroke();
  ctx.strokeStyle='#d6ae7c';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(-3,6+bob);ctx.lineTo(-5,12+bob);ctx.moveTo(3,6+bob);ctx.lineTo(5,12+bob);ctx.stroke();
  ctx.restore();
}

